import type { MelItem } from '../types';

/**
 * MEL **Section Two (CAS Message Relief)** and the **NEF Deferral List**, extracted from the two
 * approved P&G D195 MELs — the same source documents behind `mel.ts`, which holds Section One.
 * 495 items: 208 Section Two + 287 NEF.
 *
 * WHY THIS IS A SEPARATE FILE. `mel.ts` is a generated dump of Section One and is regenerated
 * wholesale; keeping these here means a Section One re-extraction cannot silently drop them, and
 * the provenance of each half stays legible. Both are spread into the seed together in
 * `scenarios.ts`.
 *
 * Two fields on every row are DERIVED rather than copied, and are the only two:
 *  - NEF `placardText` — the NEF Deferral List states the placard rule once in its page header,
 *    for every item on the list, rather than repeating it per row.
 *  - NEF `flightCrewDeferral: true` — MEL item 25-22-01, the item through which the FAA grants the
 *    NEF program its authority, is marked "Flight Crew Deferral Item: YES" in both MELs.
 *
 * Everything else is a verbatim slice of the document. Section Two items carry no `ataReference`
 * because the MEL keys that section by CAS message; NEF items carry no `category` because the
 * program gives them no repair interval (D69). Five Section Two rows take their message text from
 * the row above them — the MEL's own convention for a sub-variant (e.g. 2-32, the both-sides
 * variant of 2-31 "Wing Anti-Ice Maint Reqd, L-R"), which leaves the Item column blank.
 *
 * Regenerate with `scripts/extract_mel_sections.py` over `pdftotext -layout` output. Do not
 * hand-edit: an MEL correction belongs in the source document first (D23 four-eyes governs the
 * real table).
 */
