    "provisos": "(O) Except for ER operations, airplane may be dispatched with one CPCS failed provided: a) Manual pressurization control system is operative and functionally checked, b) Cabin altitude and differential pressure indicators are operative, c) Cabin rate-of-climb indicator is operative, d) Autopilot is operative, and e) Repairs are made within 2 flight-days."
