    "oProcedure": "Flightcrew will ensure: 1. FMS position is checked against available sensors, and 2. If errors encountered, affected GPS is de-selected as a position sensor and FMS position is updated.",
    "provisos": "(O) Airplane may be dispatched provided: a) FMS position is checked against available sensors, and b) If errors encountered, affected GPS is de-selected as a position sensor and FMS position is updated."
