    "provisos": "(O) Airplane may be dispatched provided: a) Affected forward battery is swapped with aft battery (#2 IRU and #3 IRU backup battery position) and thus Fwd Emer Battery Volts CAS then clears, b) All other components of the electrical system are operative, c) All three IRSs and both AHRSs are operational, and d) Repairs are made within 1 flight-day. NOTE 1: EICAS message “IRU Sec Pwr 2 – 3 Fail” will be displayed. Each MAIN AC BUS can be powered by the L GEN, R GEN, and APU. NOTE 2: IRU No. 1 is powered by the Fwd Emerg Batt or by the L ESS DC BUS. Only one IRS is required for the flight controls to remain in normal mode."
