    "casColor": "CYAN",
    "casLevel": "ADVISORY",
    "oProcedure": "Flightcrew may allow passengers to use the lavatories provided the passengers are briefed on the necessity to ensure that no flammable materials are used in the lavatory.",
    "provisos": "(O) Airplane may be dispatched provided for each affected lavatory: a) Lavatory waste receptacle is empty, b) Associated lavatory door is locked closed and placarded “INOPERATIVE – DO NOT ENTER”, and c) Lavatory is used only by crewmembers. NOTE: These provisos are not intended to prohibit lavatory use or inspections by crewmembers."
