    "oProcedure": "Flightcrew will ensure: 1. At least one Pilot and Copilot TSC is operative, 2. Affected Observer CAU: CPOP, G-2 circuit breaker is pulled and collared, 3. It is not required as determined by the PIC, 4. Flight Deck to cabin communication is operative, and 5. Procedures as noted in the Operations procedure are followed.",
