    "oProcedure": "Flightcrew will ensure: 1. All Display Units are operative, and 2. Inoperative TSC CB/SSPC is pulled and collared: •     TSC 1 PWR: SSPC 3123, •     TSC 4 PWR: 3127, •     TSC 5A PWR: SSPC 3129, or •     TSC 5B PWR: SSPC 3130.",
