    "casColor": "CYAN",
    "casLevel": "ADVISORY",
    "oProcedure": "Flightcrew will ensure: 1. At least one radio altimeter is valid, 2. Procedures as noted in the Operations procedure are followed, and 3. Flightcrew will comply with AFM/AOM guidance in windshear situations and recommend procedures when encountering windshear.",
    "provisos": "(O) Airplane may be dispatched provided: a) At least one radio altimeter is valid, b) Procedures as noted in the Operations procedure are followed, c) Flightcrew comply with AFM/AOM guidance in windshear situations and recommend procedures when encountering windshear, and d) Repairs are made within 2 flight-days. NOTE: Operator’s alternate procedures should include reviewing windshear avoidance and windshear recovery procedures."
